def closestValue(nums, target):
    n = len(nums)
    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < nums[mid + 1]:
            lo = mid + 1
        else:
            hi = mid
    peak = lo
    best = None

    def consider(v):
        nonlocal best
        if best is None or (abs(v - target), v) < (abs(best - target), best):
            best = v

    a, b = 0, peak + 1
    while a < b:
        m = (a + b) // 2
        if nums[m] >= target:
            b = m
        else:
            a = m + 1
    for i in (a - 1, a):
        if 0 <= i <= peak:
            consider(nums[i])
    a, b = peak + 1, n
    while a < b:
        m = (a + b) // 2
        if nums[m] <= target:
            b = m
        else:
            a = m + 1
    for i in (a - 1, a):
        if peak + 1 <= i < n:
            consider(nums[i])
    return best
